use vstd::prelude::*;

verus! {
    fn remove_duplicates(nums: &Vec<i32>) -> (result: usize)
        requires
            nums.len() <= usize::MAX,
        ensures
            result <= nums.len(),
            result == count_distinct(nums),
    {
        if nums.len() == 0 {
            return 0;
        }

        let mut count: usize = 1; // Start with 1 for the first unique element
        let mut i: usize = 1; // Start from the second element

        while i < nums.len()
            invariant
                1 <= count <= nums.len(),
                i <= nums.len(),
                nums[i - 1] <= nums[i],
                count == count_distinct(&nums[0..i]),
            decreases nums.len() - i,
        {
            if nums[i] != nums[i - 1] {
                count = count + 1; // Found a new unique element
            }
            i = i + 1;
        }

        count
    }

    // Helper function to count distinct values in the first n elements of the array
    spec fn count_distinct(nums: &Vec<i32>) -> usize
        requires
            nums.len() <= usize::MAX,
    {
        if nums.len() == 0 {
            0
        } else {
            let mut distinct_count: usize = 1; // Start with the first element
            let mut prev: i32 = nums[0];

            for i in 1..nums.len() {
                if nums[i] != prev {
                    distinct_count = distinct_count + 1;
                    prev = nums[i];
                }
            }
            distinct_count
        }
    }
}

